// Toma del Error Trigger solo los identificadores del fallo: el flujo, el último nodo y el id de la ejecución (C2,
// HU0002). El mensaje del error NO se envía: puede traer correos u otros datos personales. La API lo deja en su log y
// la ejecución fallida se revisa en n8n con su id.
const unaLinea = (valor, maximo, porDefecto) => {
  const texto = String(valor ?? '').replace(/[\u0000-\u001f\u007f-\u009f]/g, ' ').trim().slice(0, maximo);
  return texto || porDefecto;
};

return $input.all().map((item, indice) => {
  const e = item.json ?? {};
  const id = String(e.execution?.id ?? '');
  return {
    json: {
      flujo: unaLinea(e.workflow?.name, 60, 'desconocido'),
      nodo: unaLinea(e.execution?.lastNodeExecuted ?? e.trigger?.error?.node?.name, 100, 'desconocido'),
      id_ejecucion: /^[0-9A-Za-z-]{1,40}$/.test(id) ? id : 'sin-id',
    },
    pairedItem: { item: indice },
  };
});
